const { spawn } = require('child_process');
const fs = require('fs');
const fetch = require('node-fetch');

async function runTests() {
  const server = spawn('node', ['/home/user/webhook_server.js'], {
    env: { ...process.env, CROSSMINT_API_KEY: 'test-api-key' }
  });

  // Wait for server to start
  await new Promise(resolve => setTimeout(resolve, 2000));

  let healthCheck = false;
  let webhookResponse = null;

  try {
    const healthRes = await fetch('http://localhost:3000/health');
    if (healthRes.ok) {
      const healthData = await healthRes.json();
      healthCheck = healthData.status === 'ok';
    }
  } catch (err) {
    console.error('Health check failed', err);
  }

  try {
    const webhookRes = await fetch('http://localhost:3000/webhook/purchase', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        purchaseId: 'order_123',
        customerEmail: 'test@example.com',
        productName: 'Premium Widget',
        amount: 99.99
      })
    });
    webhookResponse = await webhookRes.json();
  } catch (err) {
    console.error('Webhook request failed', err);
    webhookResponse = { error: err.message };
  }

  const report = {
    health_check: healthCheck,
    webhook_response: webhookResponse
  };

  fs.writeFileSync('/home/user/webhook_test_report.json', JSON.stringify(report, null, 2));

  server.kill();
  process.exit(0);
}

runTests();

